\set ON_ERROR_STOP on
begin;
do $$begin if inet_server_addr()is not null or current_database()<>'gallery_append_capacity_proof'then raise exception'Use only owned socket fixture';end if;end$$;
create temp table checks(label text primary key);
grant all on checks to service_role;
create function pg_temp.ok(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception'APPEND CAPACITY FAIL: %',label;end if;insert into checks values(label);end$$;
create function pg_temp.denied(command text,label text,expected text default'RP400:')returns void language plpgsql as $$declare message text;begin begin execute command;exception when others then message:=sqlerrm;end;perform pg_temp.ok(message like expected||'%',label);end$$;
-- BEGIN FIXTURE
create temp table af(actor uuid,other_actor uuid,org uuid,other_org uuid,listing uuid,other_listing uuid,ids uuid[],unready uuid,foreign_id uuid);
do $$declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();o uuid;other_o uuid;l uuid:=gen_random_uuid();other_l uuid:=gen_random_uuid();ids uuid[]:='{}';asset uuid;u uuid:=gen_random_uuid();f uuid:=gen_random_uuid();n integer;begin
 insert into auth.users(id,email,is_anonymous)values(a,'append-capacity-owner@fixture.invalid',false),(b,'append-capacity-other@fixture.invalid',false);
 select org_id into o from memberships where user_id=a;select org_id into other_o from memberships where user_id=b;
 -- Capacity assertions concern an existing paid gallery, not Free creation.
 update orgs set plan='starter',plan_source='manual' where id in(o,other_o);
 insert into listings(id,org_id,agent_id,address)values(l,o,a,'Synthetic capacity home'),(other_l,other_o,b,'Other synthetic home');
 for n in 1..101 loop
  asset:=gen_random_uuid();ids:=array_append(ids,asset);
  insert into capture_assets(id,listing_id,kind,bucket,storage_key,uploaded,created_at)values(asset,l,'photo','renders','renders/'||o||'/'||l||'/gallery-'||asset||'.jpg',true,'2026-01-01 00:00:00Z'::timestamptz+n*interval'1 second');
 end loop;
 insert into capture_assets(id,listing_id,kind,bucket,storage_key,uploaded)values(u,l,'photo','renders','renders/'||o||'/'||l||'/gallery-'||u||'.jpg',false),(f,other_l,'photo','renders','renders/'||other_o||'/'||other_l||'/gallery-'||f||'.jpg',true);
 insert into af values(a,b,o,other_o,l,other_l,ids,u,f);
end$$;
grant select on af to service_role;
-- END FIXTURE
select pg_temp.ok(has_function_privilege('service_role','public.append_listing_gallery(uuid,uuid,uuid,uuid[],boolean,text)','execute')and not has_function_privilege('authenticated','public.append_listing_gallery(uuid,uuid,uuid,uuid[],boolean,text)','execute')and not has_function_privilege('anon','public.append_listing_gallery(uuid,uuid,uuid,uuid[],boolean,text)','execute'),'existing service-only ACL preserved');
set local role service_role;
do $$declare f record;r jsonb;before_row jsonb;k text;begin select *into f from af;k:='renders/'||f.org||'/'||f.listing||'/gallery-'||f.ids[1]||'.jpg';
 update listings set gallery_asset_ids='{}'::uuid[]where id=f.listing;
 r:=append_listing_gallery(f.actor,f.org,f.listing,f.ids[1:41]);
 perform pg_temp.ok((select gallery_asset_ids=f.ids[1:41]from listings where id=f.listing),'41 distinct additions are admitted in exact request order');
 update listings set gallery_asset_ids='{}'::uuid[],main_photo_key=null where id=f.listing;
 r:=append_listing_gallery(f.actor,f.org,f.listing,f.ids[1:100],true,k);
 perform pg_temp.ok((select gallery_asset_ids=f.ids[1:100]and main_photo_key=k from listings where id=f.listing),'100 distinct additions and exact cover admitted');
 r:=append_listing_gallery(f.actor,f.org,f.listing,f.ids[1:100]);
 perform pg_temp.ok((select gallery_asset_ids=f.ids[1:100]and main_photo_key=k from listings where id=f.listing),'repeat100 preserves order without duplicate IDs');
 select to_jsonb(l)into before_row from listings l where id=f.listing;
 perform pg_temp.denied(format('select append_listing_gallery(%L,%L,%L,%L::uuid[])',f.actor,f.org,f.listing,f.ids),'101 input IDs refuse before mutation','RP400: Choose up to 100 distinct');
 perform pg_temp.ok((select to_jsonb(l)=before_row from listings l where id=f.listing),'oversized request leaves selection and cover untouched');
 perform pg_temp.denied(format('select append_listing_gallery(%L,%L,%L,array[%L]::uuid[])',f.actor,f.org,f.listing,f.ids[101]),'101st union refuses own capacity fence','RP400: The published gallery can contain up to 100');
 perform pg_temp.ok((select to_jsonb(l)=before_row from listings l where id=f.listing),'union overflow leaves unknown selections and cover untouched');
 update listings set gallery_asset_ids=f.ids[1:99],main_photo_key=k where id=f.listing;
 r:=append_listing_gallery(f.actor,f.org,f.listing,array[f.ids[100]]);
 perform pg_temp.ok((select gallery_asset_ids=f.ids[1:100]and main_photo_key=k from listings where id=f.listing),'99 existing plus one reaches100 without replacing oldIDs');
 update listings set gallery_asset_ids=array[f.ids[5],f.ids[2]],main_photo_key=null where id=f.listing;
 r:=append_listing_gallery(f.actor,f.org,f.listing,array[f.ids[4]]);
 perform pg_temp.ok((select gallery_asset_ids=array[f.ids[5],f.ids[2],f.ids[4]]from listings where id=f.listing),'unknown existing IDs retain order and newID appends');
 perform pg_temp.ok((select not(f.ids[1]=any(gallery_asset_ids))and not(f.ids[3]=any(gallery_asset_ids))from listings where id=f.listing),'explicit excluded originals are not rebuilt from capturelibrary');
 update listings set gallery_asset_ids='{}'::uuid[],main_photo_key=null where id=f.listing;
 r:=append_listing_gallery(f.actor,f.org,f.listing,'{}'::uuid[]);
 perform pg_temp.ok((select gallery_asset_ids='{}'::uuid[]and main_photo_key is null from listings where id=f.listing),'explicit empty remains empty without legacy fallback');
 r:=append_listing_gallery(f.actor,f.org,f.listing,array[f.ids[100]]);
 perform pg_temp.ok((select gallery_asset_ids=array[f.ids[100]]from listings where id=f.listing),'explicit empty adds only explicitly requested asset');
 update listings set gallery_asset_ids=null,main_photo_key=k where id=f.listing;
 r:=append_listing_gallery(f.actor,f.org,f.listing,'{}'::uuid[]);
 perform pg_temp.ok((select gallery_asset_ids=f.ids[1:100]and main_photo_key=k from listings where id=f.listing),'NULL automatic conversion preserves full100 existing visible choices');
 update listings set gallery_asset_ids=null,main_photo_key=k where id=f.listing;
 perform pg_temp.denied(format('select append_listing_gallery(%L,%L,%L,array[%L]::uuid[])',f.actor,f.org,f.listing,f.ids[101]),'NULL conversion refuses101st instead of discarding an oldphoto','RP400: The published gallery can contain up to 100');
 perform pg_temp.ok((select gallery_asset_ids is null and main_photo_key=k from listings where id=f.listing),'failed NULL conversion retains prior automatic state');
 update listings set gallery_asset_ids=array[f.ids[1]],main_photo_key=k where id=f.listing;
 select to_jsonb(l)into before_row from listings l where id=f.listing;
 perform pg_temp.denied(format('select append_listing_gallery(%L,%L,%L,array[%L]::uuid[])',f.other_actor,f.org,f.listing,f.ids[2]),'outsider cannot use privileged append','RP404:');
 perform pg_temp.denied(format('select append_listing_gallery(%L,%L,%L,array[%L]::uuid[])',f.actor,f.other_org,f.listing,f.ids[2]),'wrong org cannot append','RP404:');
 perform pg_temp.denied(format('select append_listing_gallery(%L,%L,%L,array[%L]::uuid[])',f.actor,f.org,f.listing,f.foreign_id),'foreign listing asset refused');
 perform pg_temp.denied(format('select append_listing_gallery(%L,%L,%L,array[%L]::uuid[])',f.actor,f.org,f.listing,f.unready),'incomplete asset refused');
 perform pg_temp.denied(format('select append_listing_gallery(%L,%L,%L,array[%L,%L]::uuid[])',f.actor,f.org,f.listing,f.ids[2],f.ids[2]),'duplicate request refused');
 perform pg_temp.denied(format('select append_listing_gallery(%L,%L,%L,null)',f.actor,f.org,f.listing),'null request refused');
 perform pg_temp.denied(format('select append_listing_gallery(%L,%L,%L,array[null]::uuid[])',f.actor,f.org,f.listing),'null ID refused');
 perform pg_temp.ok((select to_jsonb(l)=before_row from listings l where id=f.listing),'all invalid requests preserve prior row');
 update orgs set deleted_at=now()where id=f.org;
 perform pg_temp.denied(format('select append_listing_gallery(%L,%L,%L,array[%L]::uuid[])',f.actor,f.org,f.listing,f.ids[2]),'deleted org refused','RP404:');
 update orgs set deleted_at=null where id=f.org;
 r:=append_listing_gallery(f.actor,f.org,f.listing,array[f.ids[2]],true,'renders/'||f.org||'/'||f.listing||'/gallery-'||f.ids[2]||'.jpg');
 perform pg_temp.ok((select gallery_asset_ids=array[f.ids[1],f.ids[2]]and main_photo_key='renders/'||f.org||'/'||f.listing||'/gallery-'||f.ids[2]||'.jpg'from listings where id=f.listing),'cover replacement remains atomic');
 r:=append_listing_gallery(f.actor,f.org,f.listing,'{}'::uuid[],true,null);
 perform pg_temp.ok((select gallery_asset_ids=array[f.ids[1],f.ids[2]]and main_photo_key is null from listings where id=f.listing),'explicit cover clear preserves selected IDs');
 perform pg_temp.ok((select count(*)=102 from capture_assets where listing_id=f.listing),'append never changes or deletes original media rows');
end$$;
reset role;
select jsonb_build_object('passed',true,'assertions',(select count(*)from checks));
rollback;
